/* Independent menu design workspace. Business facts remain local. */
const M=MenuModel,R=MenuRenderer,Ref=MenuReference,E=R.esc,KEY='menu-design-draft-v1';
let saved=null;try{saved=JSON.parse(localStorage.getItem(KEY));if(saved?.schema!==1)saved=null}catch{}
let s=saved||M.create(),home=true,busy=null,error='',files=[],undo=[],failGenerate=false,failExport=false,saveFailed=false,job=0;
M.ensureBrand(s);M.ensureIntent(s);M.migrateWorkflow(s);Ref.ensure(s);if(M.migrateDevicePresets(s)){Ref.invalidate(s);s.generated=false;s.maxStep=Math.min(s.maxStep,5);s.step=Math.min(s.step,5);s.overrides={};}if(s.reference.analysis.status==='running')s.reference.analysis.status='cancelled';if(!Ref.ready(s)&&s.maxStep>5){s.maxStep=5;s.step=Math.min(s.step,5);s.generated=false;}if(saved)saved=structuredClone(s);
const steps=['用途规格','设计意图','菜单材料','材料体检','视觉方向','页面规划','编辑菜单','检查导出'];
const captions=['决定成品用在哪里','先确认页面要求与经营重点','选择商品与品牌素材','补齐影响设计的材料','参考你喜欢的构图与气质','确认内容如何分布','微调，让它更像你','带走可用的菜单文件'];
const originalCanContinue=M.canContinue;M.canContinue=state=>state.step===5?(M.canGenerate(state)&&Ref.ready(state)):originalCanContinue(state);
const hints=['规格决定画布比例与导出尺寸。','先确定页面目标、语言和内容密度，下一步再选商品。','选择商品后，再指定本次菜单的主推商品。','价格属于经营事实，请由你确认。','选择参考图，确认特征与真实内容样稿，再进入页面规划。','确认数量与页序，再开始生成。','点击菜品选择组件；拖动或在右侧调整。','导出前逐项确认，导出仅使用当前冻结版本。'];
const btn=(label,action,id='',cls='',disabled=false)=>`<button class="btn ${cls}" data-action="${action}" data-id="${E(id)}" ${disabled?'disabled':''}>${label}</button>`;
let controlSequence=0;
const field=(label,key,value,type='text',extra='')=>{const id=`f-${key}-${++controlSequence}`;return `<div class="field"><label for="${id}">${label}</label><input id="${id}" data-field="${key}" type="${type}" value="${E(value)}" ${extra}></div>`};
const select=(label,key,value,options)=>{const id=`f-${key}-${++controlSequence}`;return `<div class="field"><label for="${id}">${label}</label><select id="${id}" data-field="${key}">${options.map(([v,l])=>`<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${l}</option>`).join('')}</select></div>`};
const check=(label,key,value)=>`<label class="check-label"><input type="checkbox" data-field="${key}" ${value?'checked':''}>${label}</label>`;
const notice=(text,type='')=>`<div class="notice ${type}"><span>${type==='bad'?'!':type==='good'?'✓':'ⓘ'}</span><span>${text}</span></div>`;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3000)}
function save(){s.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(s));saved=structuredClone(s);saveFailed=false}catch{saveFailed=true;toast('浏览器存储空间不足，当前更改尚未保存；可减少上传图片。')}}
function checkpoint(){undo.push(structuredClone(s));if(undo.length>20)undo.shift()}
function clearFiles(){for(const f of files)URL.revokeObjectURL(f.url);files=[]}
function dirty(regenerate=false){clearFiles();s.exportWarning=false;s.pdfWarning=false;if(regenerate){Ref.invalidate(s);s.generated=false;s.maxStep=Math.min(s.maxStep,s.checked?5:4);s.overrides={};s.page=0;s.pageOrder=[]}s.revision++;save()}
function modal(title,body,footer=''){const d=document.querySelector('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2>${btn('关闭','close','','ghost sm')}</div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;d.showModal()}
function close(){document.querySelector('#dialog').close()}
function header(){return `<header class="topbar"><div class="brand"><span class="brand-mark">m</span>Menu Studio</div><span class="divider"></span><span class="top-title">${home?'静态电子菜单设计':E(s.name)}</span><span class="badge">交互原型 v0.4</span><span class="spacer"></span>${!home?`<span class="save"><i class="dot"></i>${saveFailed?'尚未保存':'已保存到本机'}</span>`:''}${btn('原型说明','about','','ghost sm')}${!home?btn('项目首页','home','','sm'):''}<span class="avatar">山</span></header>`}
function homeView(){const demo=M.create();demo.items[5].price=36;demo.noImage=true;return `${header()}<main class="home"><div class="prototype-banner"><span class="badge good">PHASE 01</span>只做一件事：设计电子菜单，导出图片或 PDF。</div><div class="home-heading"><div><h1>让一份好菜单，从这里开始。</h1><p>不需要懂设计。准备菜单材料，跟着引导完成你的第一份作品。</p></div>${btn('＋ 创建菜单','new','','primary')}</div><div class="home-layout"><div><article class="project-card"><div class="project-cover"><div class="sheet-back"></div>${R.svg(demo,M.pages(demo)[0])}</div><div class="project-meta"><div><h3>山野食堂 · 秋日菜单</h3><small>示例项目 · 12 道商品 · 自然质感 · 横屏</small></div><span class="spacer"></span>${btn('从示例开始 →','new','','primary')}</div></article>${saved?`<section class="section saved-project"><div class="row"><span class="badge">本机草稿</span><h3>${E(saved.name)}</h3></div><p class="hint">上次停在「${steps[saved.step-1]}」，${new Date(saved.updatedAt).toLocaleString('zh-CN')}</p><div class="row">${btn('继续设计','resume','','primary')}${btn('复制项目','duplicate','','')}</div></section>`:''}</div><aside class="home-side"><h3>从想法到成品，步步有引导</h3>${[['确认页面要求','先定用途规格、设计目标与内容密度。'],['准备商品与方向','选商品、补材料，再选择参考图与样稿。'],['生成与微调','确认分页，调整文字、图片与位置。'],['检查并导出','下载 PNG、JPG 或多页 PDF。']].map((x,i)=>`<div class="timeline-row"><span class="num">${i+1}</span><div><strong>${x[0]}</strong><p>${x[1]}</p></div></div>`).join('')}<div class="preview-only">这是设计确认原型。生成过程采用本地规则演示，未接入 AI 或餐厅业务数据。</div></aside></div><div class="home-foot"><span>✓ 可编辑的静态设计</span><span>✓ 本机保存草稿</span><span>✓ 实际下载图片 / 预览 PDF</span><span>不包含点餐、支付和设备发布</span></div></main>`}
function specifications(){return `<section class="section"><div class="section-head"><h2>菜单准备放在哪里？</h2><small>选择后可以返回修改</small></div><div class="grid three">${[['landscape','电视横屏','1920 × 1080 px','16:9',''],['portrait','竖屏海报','1080 × 1920 px','9:16','portrait'],['a4','打印 / PDF','A4 · 210 × 297 mm','A4','print'],['ipad-mini-6','iPad mini 6','2266 × 1488 px · 默认横屏','横屏',''],['ipad-8','iPad 8','2160 × 1620 px · 默认横屏','4:3',''],['ipad-9','iPad 9','2160 × 1620 px · 默认横屏','4:3',''],['ipad-10','iPad 10','2360 × 1640 px · 默认横屏','横屏',''],['screen-2000-1200','2000 × 1200','2000 × 1200 px · 默认横屏','5:3',''],['screen-1920-1200','1920 × 1200','1920 × 1200 px · 默认横屏','16:10','']].map(x=>`<button class="choice ${s.profile===x[0]?'selected':''}" data-action="profile" data-id="${x[0]}"><span class="device"><span class="device-screen ${x[4]}">${x[3]}</span></span><strong>${x[1]}</strong><small>${x[2]}</small>${s.profile===x[0]?'<span class="tick">✓</span>':''}</button>`).join('')}</div><div class="row" style="margin-top:16px">${btn('A3 打印','profile','a3','sm')}${btn('自定义尺寸','profile','custom','sm')}<span class="hint">当前：${s.width} × ${s.height} ${s.unit}</span>${['ipad-mini-6','ipad-8','ipad-9','ipad-10','screen-2000-1200','screen-1920-1200'].includes(s.profile)?btn(s.width>s.height?'切换为竖屏':'切换为横屏','rotate-profile','','sm'):''}</div><p class="hint" style="margin-top:12px">设备预设采用屏幕原生像素尺寸，不是浏览器显示区域；更改规格需要重新确认样稿。</p></section><section class="section"><h2 style="margin-bottom:19px">项目设置</h2>${field('项目名称','name',s.name,'text','maxlength="40"')}${s.profile==='custom'?`<div class="fields">${field('宽度（px）','width',s.width,'number','min="100" max="4096"')}${field('高度（px）','height',s.height,'number','min="100" max="4096"')}</div><p class="hint">原型支持 100–4096 px。更改规格需要重新生成。</p>`:''}${s.unit==='mm'?select('图片导出清晰度','dpi',s.dpi,[[150,'150 DPI · 预览'],[300,'300 DPI · 高清']]):''}${notice('本阶段输出静态图片与 PDF，不会创建可点击点餐页面。')}</section>`}
function materials(){M.ensureBrand(s);if(!M.items(s).some(x=>x.id===s.featured))s.featured='';return `<section class="section"><div class="section-head"><h2>品牌材料</h2><span class="badge">本机处理 · 不上传云端</span></div><div class="fields">${field('餐厅名称 *','brand',s.brand,'text','maxlength="16"')}${field('品牌短句','subtitle',s.subtitle,'text','maxlength="40"')}</div><div class="asset-drop"><span class="thumb">${s.logo?`<img alt="品牌 Logo" src="${s.logo}">`:'山'}</span><div><strong>品牌 Logo（可选）</strong><small>PNG / JPG，最大 5 MB；未上传时使用文字标识。</small></div><span class="spacer"></span>${btn('上传 Logo','upload-logo','','sm')}</div>${brandMaterialsView()}</section><section class="section"><div class="section-head"><h2>选择菜单内容</h2><small>已选 ${M.items(s).length} / ${s.items.length} 道商品</small></div><div class="row wrap" style="margin-bottom:15px">${M.categories.map(c=>`<button class="pill ${s.items.filter(x=>x.category===c).every(x=>x.included)?'selected':''}" data-action="category" data-id="${c}">${c}</button>`).join('')}${btn('＋ 手动新增','add-item','','sm')}</div><div class="table-wrap"><table><thead><tr><th>选用</th><th>商品 / 展示名称</th><th>价格</th><th>素材</th><th></th></tr></thead><tbody>${s.items.map(x=>`<tr><td><input aria-label="选择${E(x.name)}" type="checkbox" data-item-check="${x.id}" ${x.included?'checked':''}></td><td><div class="row"><span class="food-thumb">${x.image?`<img alt="" src="${x.image}" style="width:100%;height:100%;object-fit:cover">`:x.art?R.food(x.kind):''}</span><div>${E(x.name)}<br><small>${E(x.category)}</small></div></div></td><td>${x.price===null?'<span class="badge bad">待确认</span>':'¥ '+x.price}</td><td><span class="badge ${!x.art&&!x.image?'warn':''}">${x.image?'已上传':x.art?'示例插画':'缺少图片'}</span></td><td>${btn('编辑','edit-item',x.id,'sm ghost')}</td></tr>`).join('')}</tbody></table></div></section><section class="section"><h2 style="margin-bottom:16px">本次菜单的主推商品</h2>${select('主推商品','featured',s.featured,[['','暂不指定主推'],...M.items(s).map(x=>[x.id,E(x.name)])])}<p class="hint">仅从本次已选商品中指定；移除该商品后将清空主推选择。</p></section>`}
function materialGateView(){const pending=M.materialRequirements(s);return pending.length?`<section class="section material-gate" aria-label="生成前的材料待办"><h2>可以先选参考图，生成样稿前还需完成</h2><p class="hint">浏览、上传参考图和模拟分析不受影响。完成以下事项后即可生成样稿；不会自动修改你的商品或价格。</p><ul>${pending.map(t=>`<li>${E(t)}</li>`).join('')}</ul>${btn('前往材料体检','goto',4,'sm')}</section>`:'';}
function inspection(){const q=M.issues(s);return `<section class="section"><div class="section-head"><h2>${s.checked?'材料检查报告':'先检查，再开始设计'}</h2>${btn(s.checked?'重新检查':'开始检查','check','','primary')}</div><div class="stats"><div><strong>${M.items(s).length}</strong><small>已选商品</small></div><div><strong style="color:var(--bad)">${q.blockers.length}</strong><small>需要补齐</small></div><div><strong style="color:var(--warning)">${q.missing.length}</strong><small>缺少图片</small></div></div>${!s.checked?notice('点击开始检查，确认内容是否适合生成。你也可以先浏览视觉方向，生成样稿前再回来完成检查。'):q.blockers.map(t=>`<div class="issue"><span class="state-icon">!</span><div class="body"><h3>${E(t)}</h3><p>这是一项阻断问题，补齐后才能继续。</p><div class="issue-actions">${btn('前往修复','repair','','sm')}</div></div></div>`).join('')}${s.checked?`<div class="issue"><span class="state-icon ${s.noImage||!q.missing.length?'good':'warn'}">${s.noImage||!q.missing.length?'✓':'!'}</span><div class="body"><h3>${q.missing.length?'缺图商品：'+q.missing.map(x=>E(x.name)).join('、'):'商品图片完整'}</h3><p>无图商品可使用文字版式，或返回材料页上传真实照片。</p><div class="issue-actions">${btn(s.noImage?'✓ 已选择无图版式':'缺图商品使用无图版式','no-image','','sm',!q.missing.length)}${btn('返回材料页','goto',3,'sm ghost')}</div></div></div><div class="issue"><span class="state-icon warn">!</span><div class="body"><h3>示例插画仅用于体验</h3><p>示例图与真实菜品不等同；正式交付前请替换为商家确认的照片。</p>${check('我了解当前使用示例插画','warnings',s.warnings)}</div></div>`:''}</section>${!M.canGenerate(s)?`<section class="section"><p class="hint">材料体检暂不影响浏览和选择参考图；生成样稿时仍需完成检查。</p>${btn('先浏览视觉方向','goto',5)}</section>`:''}${s.checked&&!q.blockers.length&&(!q.missing.length||s.noImage)&&s.warnings?notice('材料已准备好，可以选择参考图与视觉方向。','good'):''}`}
let intentAdvancedOpen=false;
const intentFields=['readingScene','contentFocus','organization','showBrand','showCategories','showDescription','showRecommendation','showPromotion','intentNotes'];
function updateIntent(key,value){if(!intentFields.includes(key))return;checkpoint();M.ensureIntent(s);s[key]=value;dirty(true);render();}
function intention(){M.ensureIntent(s);return `${notice('先说明这份菜单想达到什么效果。具体商品下一步选择，视觉风格随后通过参考图确定。')}
<section class="section"><div class="section-head"><h2>01 这份菜单的核心目标是什么？</h2><span class="badge">选择一个主要目标</span></div><div class="grid three" style="margin-top:18px">${[['突出招牌','让顾客先看到值得推荐的菜'],['新品上市','重点展示本次上新的内容'],['套餐推荐','清楚表达组合内容与价格'],['优惠促销','突出已确认的优惠信息'],['完整展示','有层次地呈现全部所选商品'],['快速选择','让顾客更快看清名称与价格'],['传递质感','通过留白与层级体现品牌质感']].map(x=>`<button class="choice ${s.goal===x[0]?'selected':''}" data-action="goal" data-id="${x[0]}" aria-pressed="${s.goal===x[0]}"><strong>${x[0]}</strong><small>${x[1]}</small></button>`).join('')}</div></section>
<section class="section"><h2 style="margin-bottom:19px">02 顾客会怎样阅读？</h2><div class="fields">${select('阅读场景','readingScene',s.readingScene,[['桌面平板近看','桌面平板近看'],['柜台浏览','柜台浏览'],['墙面远看','墙面远看']])}${select('信息密度 / 每页商品数量','density',s.density,[[2,'大图少量 · 每页最多 2 道'],[4,'图文均衡 · 每页最多 4 道'],[6,'信息丰富 · 每页最多 6 道']])}</div><p class="hint">远距离阅读建议选“大图少量”；近距离可选“图文均衡”。实际页数在选定商品后计算。</p></section>
<details class="section intent-advanced" ${intentAdvancedOpen?'open':''}><summary style="cursor:pointer;font-size:15px;font-weight:600">更多设计要求 <span class="hint">语言、信息重点、展示元素与补充说明</span></summary><div style="margin-top:22px"><div class="fields">${select('显示语言','language',s.language,[['双语','中文 + 英文（示例译名）'],['中文','仅中文']])}${select('信息重点','contentFocus',s.contentFocus,[['菜品图片','菜品图片'],['名称价格','名称价格'],['口味介绍','口味介绍'],['套餐内容','套餐内容']])}${select('内容组织','organization',s.organization,[['交给智能体建议','交给智能体建议'],['按分类','按分类'],['主推优先','主推优先'],['套餐组合','套餐组合']])}</div><h3 style="margin:18px 0 12px">希望包含哪些展示元素？</h3><div class="fields">${check('品牌标识','showBrand',s.showBrand)}${check('分类标题','showCategories',s.showCategories)}${check('商品描述（需提供内容）','showDescription',s.showDescription)}${check('推荐标签（需指定商品）','showRecommendation',s.showRecommendation)}${check('活动说明','showPromotion',s.showPromotion)}</div><p class="hint">菜名与价格始终保留。描述、推荐、套餐与优惠只能使用后续确认的材料，不自动编造。</p>${field('页脚活动说明（可选）','promo',s.promo,'text','maxlength="45" placeholder="例如：工作日午间套餐，欢迎询问店员"')}${field('补充设计要求（可选）','intentNotes',s.intentNotes,'text','maxlength="180" placeholder="例如：价格醒目，不要太多装饰"')}</div></details>
${notice('原型范围：语言、每页数量和活动短句已影响样稿；新增场景、信息重点、组织与元素偏好作为设计摘要保存，尚未接入自动排版。')}
`;}

function planning(){const pages=M.pages(s);return `<section class="section"><div class="section-head"><h2>${pages.length} 页菜单，${M.items(s).length} 道商品</h2>${select('每页数量','density',s.density,[[2,'2 道'],[4,'4 道'],[6,'6 道']])}</div>${pages.map((p,i)=>`<div class="page-row"><div class="page-mini">${R.svg(s,p)}</div><div class="page-info"><strong>第 ${i+1} 页 · ${E(p.items[0]?.category||'菜单')}</strong><small>${p.items.map(x=>E(x.name)).join(' · ')}</small><small>${p.items.length} 道商品 · ${s.width} × ${s.height} ${s.unit}</small></div>${btn('↑','page-up',i,'sm',i===0)}${btn('↓','page-down',i,'sm',i===pages.length-1)}</div>`).join('')}</section>${error?notice(E(error),'bad'):''}${s.generated?notice('菜单已生成。你可以进入编辑，或重新生成当前方案。','good'):notice('这里展示规则布局预览；确认后生成可编辑菜单。')}<div class="row">${btn(s.generated?'重新生成全部页面':'生成我的菜单','generate','','primary')}<small>本地规则演示 · 不调用 AI</small></div>`}
function editor(){const pages=M.pages(s),p=pages[s.page]||pages[0];return `<div class="canvas-toolbar"><span class="toolbar-label">第 ${s.page+1} / ${pages.length} 页 · ${s.width} × ${s.height} ${s.unit}</span>${btn('撤销','undo','','sm',!undo.length)}${btn('重生成当前页','regenerate','','sm')}${btn('放大预览','preview','','sm')}</div>${error?notice(E(error),'bad'):''}<div class="canvas-area" id="editor-canvas">${R.svg(s,p,s.selected)}</div><div class="page-strip">${pages.map((p,i)=>`<button class="page-tab ${s.page===i?'selected':''}" data-action="page" data-id="${i}">${R.svg(s,p)}<span>第 ${i+1} 页 · ${p.items.length} 道商品</span></button>`).join('')}</div><p class="hint">点击任一菜品卡片，在右侧调整；蓝色虚线仅为选中提示，不会导出。</p><div class="mobile-inspector">${inspector()}</div>`}
function inspector(){const x=s.items.find(x=>x.id===s.selected),p=M.pages(s)[s.page],pos=x&&R.positions(s,p).find(z=>z.item.id===x.id),o=s.overrides[s.selected]||{};return `<div class="aside-section"><h3>组件属性</h3>${x&&pos?`<span class="selected-label">${o.locked?'已锁定 · 重生成将保留':'已选择 · 菜品卡片'}</span><div class="component-name">${E(x.name)}</div>${field('展示名称','component-name',x.name,'text','maxlength="18"')}${field('售价（¥）','component-price',x.price,'number','min="0" step="0.01"')}<div class="inline-fields">${field('X 位置','component-x',Math.round(pos.x),'number','step="5"')}${field('Y 位置','component-y',Math.round(pos.y),'number','step="5"')}</div>${field('缩放（0.7–1.1）','component-scale',pos.scale,'number','min="0.7" max="1.1" step="0.05"')}${select('图片显示','component-crop',o.crop||'cover',[['cover','铺满 · 居中裁切'],['contain','完整显示']])}${btn(o.locked?'解除锁定':'锁定此组件','lock','','wide')}${btn('替换菜品图片','upload-item',x.id,'wide ghost')}`:`<div class="empty-preview"><p>选择画布中的菜品<br><small>即可调整内容、位置和图片</small></p></div>`}</div><div class="aside-section"><h3>页面风格</h3><div class="swatches">${Object.entries(R.palettes).map(([k,p])=>`<button title="${k}" aria-label="切换${k}风格" class="swatch ${s.style===k?'selected':''}" style="background:${p.ink}" data-action="editor-style" data-id="${k}"></button>`).join('')}</div><p style="margin-top:13px">修改全局风格会应用到整份菜单。存在锁定组件时需先解除锁定。</p></div>`}
function layoutErrors(state=s){const {w,h}=R.dimensions(state),errors=[];for(const p of M.pages(state)){const a=R.positions(state,p);for(const z of a){if(z.x<32||z.y<145||z.x+z.cw*z.scale>w-32||z.y+z.ch*z.scale>h-52)errors.push(z.item.name+' 超出内容安全区')}for(let i=0;i<a.length;i++)for(let j=i+1;j<a.length;j++){const x=a[i],y=a[j];if(x.x<y.x+y.cw*y.scale-1&&x.x+x.cw*x.scale>y.x+1&&x.y<y.y+y.ch*y.scale-1&&x.y+x.ch*x.scale>y.y+1)errors.push(x.item.name+' 与 '+y.item.name+' 重叠')}}return [...new Set(errors)]}
function exportView(){const blockers=[...M.issues(s).blockers,...layoutErrors()],sz=M.size(s);if(files.length)return `<div class="result"><div class="result-icon">✓</div><div><h2>菜单文件已准备好</h2><p>来自设计版本 v${s.revision} · ${s.range==='all'?M.pages(s).length:1} 页 · ${s.format.toUpperCase()}</p><div class="file-list">${files.map(f=>`<div class="file-row"><span>▧</span><span>${E(f.name)}<br><small>${(f.blob.size/1024/1024).toFixed(2)} MB</small></span><span class="spacer"></span><a class="btn primary sm" href="${E(f.url)}" download="${E(f.name)}" style="text-decoration:none">下载文件</a></div>`).join('')}</div><div class="result-actions">${btn('继续编辑','goto',7)}${btn('换一种格式导出','export-again')}</div></div></div>${notice('这是原型交付文件。PDF 为栅格预览，正式产品的字体嵌入、印刷预检和内容哈希校验尚未接入。','warn')}`;
return `<section class="section"><div class="section-head"><h2>导出前检查</h2><span class="badge ${blockers.length?'bad':'good'}">${blockers.length?blockers.length+' 项阻断':'基础检查通过'}</span></div>${blockers.map(t=>notice(E(t),'bad')).join('')}${blockers.length?btn('返回编辑修复','goto',7,'sm'):notice('商品名称、价格、画布边界与组件重叠检查已通过。','good')}${s.stale&&!s.staleAccepted?notice('演示：来源菜单出现更新，请先确认使用哪个版本。','warn')+btn('查看数据差异','stale-dialog','','sm'):''}${check('我已核对名称和价格，了解示例插画不能代表真实菜品','exportWarning',s.exportWarning)}${s.format==='pdf'?`<div style="margin-top:13px">${check('我接受原型导出栅格预览 PDF（非正式矢量 / 印刷交付）','pdfWarning',s.pdfWarning)}</div>`:''}</section><section class="section"><h2 style="margin-bottom:20px">导出设置</h2><div class="fields">${select('文件格式','format',s.format,[['png','PNG · 清晰无损'],['jpg','JPG · 小体积'],['pdf','PDF · 多页预览文档']])}${select('页面范围','range',s.range,[['all','全部页面（'+M.pages(s).length+' 页）'],['current','仅当前第 '+(s.page+1)+' 页']])}</div>${field('文件名称','filename',s.filename,'text','maxlength="60"')}<div class="export-summary"><div class="kv"><span>成品规格</span><strong>${s.width} × ${s.height} ${s.unit}</strong></div><div class="kv"><span>图片分辨率</span><strong>${sz.width} × ${sz.height} px</strong></div><div class="kv"><span>多页交付</span><strong>${s.format==='pdf'?'一个多页 PDF':'按页编号，打包 ZIP'}</strong></div><div class="kv"><span>数据来源</span><strong>当前设计 v${s.revision}${s.staleAccepted?' · 已确认保留':''}</strong></div></div></section>${error?notice(E(error),'bad'):''}${btn('确认并导出','export','','primary',!exportAllowed())}`}
function exportAllowed(){return Ref.ready(s)&&s.generated&&!M.issues(s).blockers.length&&!layoutErrors().length&&s.exportWarning&&(s.format!=='pdf'||s.pdfWarning)&&(!s.stale||s.staleAccepted)&&!!s.filename.trim()&&!/[\\/:*?"<>|]/.test(s.filename)}
function sidebar(){M.ensureIntent(s);if(s.step<=2)return `<div class="aside-section"><div class="mini-title">PAGE REQUIREMENTS</div><h3>页面要求</h3><div class="kv"><span>输出规格</span><span>${s.width} × ${s.height} ${s.unit}</span></div><div class="kv"><span>设计目标</span><span>${E(s.goal)}</span></div><div class="kv"><span>显示语言</span><span>${E(s.language)}</span></div><div class="kv"><span>内容密度</span><span>每页最多 ${s.density} 道</span></div>${s.step===2?`<h3 style="margin-top:24px">你的设计意图</h3><p class="intent-summary" aria-live="polite">${E(M.intentSummary(s))}</p>`:''}<div class="notice">先确认页面要求，再选择商品。页数会在商品选定后计算。</div></div>`;if(s.step===5)return `<div class="aside-section"><div class="mini-title">REFERENCE BRIEF</div><h3>你的设计条件</h3><p>${M.items(s).length} 道商品 · ${M.pages(s).length} 页预计<br>${s.width} × ${s.height} ${s.unit}</p><div class="notice">参考构图，不复制菜名、价格与品牌。</div><h3>品牌配色要求</h3><p>${E(M.brandSummary(s))}</p><h3>设计意图摘要</h3><p>${E(M.intentSummary(s))}</p><h3>${Ref.ready(s)?'✓ 方向已确认':'等待确认参考方向'}</h3><p>先选参考，再确认样稿。商品数不同会适配分页，不会删除商品。</p></div><div class="preview-only">上传后自动演示分析流程，你可确认或修正结果。结果为预编写示例，未接入真实 AI 图像理解。</div>`;if(s.step===7)return inspector()+`<div class="aside-section"><h3>本页组件</h3><div class="lock-list">${M.pages(s)[s.page].items.map(x=>btn((s.overrides[x.id]?.locked?'锁定 · ':'')+E(x.name),'pick-component',x.id,'sm '+(s.selected===x.id?'primary':''))).join('')}</div></div>`;return `<div class="aside-section"><div class="mini-title">YOUR MENU BRIEF</div><h3>设计摘要</h3><div class="mini-paper">${R.svg(s,M.pages(s)[0])}</div><div class="kv"><span>餐厅</span><strong>${E(s.brand)}</strong></div><div class="kv"><span>输出尺寸</span><span>${s.width} × ${s.height} ${s.unit}</span></div><div class="kv"><span>选中内容</span><span>${M.items(s).length} 道 / ${M.pages(s).length} 页</span></div><div class="kv"><span>视觉方向</span><span>${{nature:'山野 · 自然',ink:'墨色 · 招牌',clean:'清晰 · 日常'}[s.style]}</span></div></div><div class="aside-section"><h3>这一步的建议</h3><p>${hints[s.step-1]}</p><div class="sticky-note"><p>你负责确认真实信息，工具负责把内容组织成清楚、美观的菜单。</p></div></div><div class="preview-only">原型演示：生成与质量建议为本地规则；未连接 POS、模型服务或设备发布。</div>`}
function loading(){if(busy.type==='analysis')return `<section class="section analysis-running" role="status" aria-live="polite"><span class="badge warn">AI 自动识别流程 · 模拟演示</span><h2>正在分析你的参考图</h2><p class="muted">演示如何读取图像、归纳风格和提出适配建议。当前未调用 AI，完成后显示预编写示例。</p><div class="analysis-running-source">${s.reference.image?'<img src="'+E(s.reference.image)+'" alt="正在分析的参考图">':''}<strong>${E(s.reference.name)}</strong></div><div class="progress" role="progressbar" aria-label="模拟分析进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${busy.progress}"><div style="width:${busy.progress}%"></div></div><div class="loading-stage">${['读取图片与视觉元素','归纳配色、字体与构图','结合商品数量与规格提出适配建议'].map((t,i)=>`<div class="loading-line ${busy.progress>(i+1)*28?'done':'active'}"><span>${busy.progress>(i+1)*28?'✓':'○'}</span>${t}（模拟）</div>`).join('')}</div>${btn('取消分析，保留参考图','cancel-job')}</section>`;if(busy.type==='reference')return `<section class="section"><h2>正在生成参考样稿</h2><p class="muted">本地规则模拟：结合已确认构图与真实商品，准备两种布局方向。</p><div class="progress"><div style="width:${busy.progress}%"></div></div>${btn('取消，保留参考图','cancel-job')}</section>`;return `<section class="section"><h2>${busy.type==='generate'?'正在组织你的菜单':'正在生成导出文件'}</h2><p class="muted" style="margin-top:10px">${busy.type==='generate'?'本地规则模拟生成过程，所有数据来自当前材料。':'只读取此次确认的冻结内容，不会混入后续修改。'}</p><div class="progress"><div style="width:${busy.progress}%"></div></div><div class="loading-stage">${(busy.type==='generate'?['读取菜单数据与设计意图','应用视觉方向与页面结构','检查内容，准备编辑画布']:['冻结当前设计版本','逐页渲染菜单成品','打包并准备下载文件']).map((t,i)=>`<div class="loading-line ${busy.progress>(i+1)*30?'done':busy.progress>i*30?'active':''}"><span>${busy.progress>(i+1)*30?'✓':'○'}</span>${t}</div>`).join('')}</div>${btn('取消，保留当前草稿','cancel-job','','sm')}</section>`}
function render(){const previous=document.querySelector('.main')?.scrollTop||0;if(home){document.querySelector('#app').innerHTML=homeView();return}const content=busy?loading():[specifications,intention,materials,inspection,()=>materialGateView()+Ref.view(s)+(error?notice(E(error),'bad'):''),planning,editor,exportView][s.step-1]();document.querySelector('#app').innerHTML=`${header()}<div class="workspace"><nav class="rail" aria-label="设计步骤"><div class="rail-label">CREATE YOUR MENU</div>${steps.map((t,i)=>`<button class="step ${s.step===i+1?'active':s.maxStep>i+1?'done':''}" data-action="goto" data-id="${i+1}" ${!M.canVisit(s,i+1)||busy?'disabled':''} ${s.step===i+1?'aria-current="step"':''}><span class="number">${s.maxStep>i+1?'✓':String(i+1).padStart(2,'0')}</span><span class="step-text">${t}<small>${i===4&&!M.canGenerate(s)?'可先浏览 · 生成前需材料体检':captions[i]}</small></span></button>`).join('')}<div class="rail-bottom">静态设计 · 图片 / PDF<br>你的草稿仅保存在当前浏览器${btn('演示场景','scenarios','','sm ghost')}</div></nav><main class="main"><div class="heading ${s.step===7?'editor-heading':''}"><div class="eyebrow">STEP ${String(s.step).padStart(2,'0')} / 08</div><h1>${steps[s.step-1]}</h1><p>${captions[s.step-1]}。${s.step===7?'先选中菜品，再进行局部调整。':''}</p></div>${content}</main><aside class="aside">${sidebar()}</aside><footer class="footer"><span class="footer-left">${busy?'处理期间可以取消':s.step===8?'成品只包含静态内容':'步骤 '+s.step+' / 8 · '+(s.step===4&&!M.canContinue(s)?'可先浏览视觉方向，生成前完成材料体检':s.step===5&&!M.canGenerate(s)?'可浏览参考图 · 生成前请完成材料体检':hints[s.step-1])}</span><div class="footer-actions">${btn('上一步','prev','','',s.step===1||!!busy)}${s.step<8?btn(s.step===6?'进入编辑':'下一步 →','next','','primary',!M.canContinue(s)||!!busy):btn('返回设计','goto',7,'',!!busy)}</div></footer></div>`;document.querySelector('.main').scrollTop=previous;}
function moveStep(n){if(!M.canVisit(s,n))return;if(n>5&&(!M.canGenerate(s)||!Ref.ready(s))){toast('请先完成材料体检并确认参考样稿');return;}s.step=n;s.selected=null;error='';save();render();document.querySelector('.main')?.scrollTo(0,0)}
function itemDialog(id){const x=s.items.find(x=>x.id===id);modal('编辑菜单材料',`<p class="hint" style="margin-bottom:17px">修改仅影响本设计，不回写餐厅商品库。</p><input type="hidden" id="item-id" value="${x.id}"><div class="field"><label for="item-name">商品名称 *</label><input id="item-name" maxlength="18" value="${E(x.name)}"></div><div class="field"><label for="item-en">英文展示名称</label><input id="item-en" maxlength="42" value="${E(x.en)}"></div><div class="field"><label for="item-price">价格（¥）*</label><input id="item-price" type="number" min="0" step="0.01" value="${x.price??''}" placeholder="请输入真实售价"></div><p id="item-error" style="color:var(--bad)"></p><div class="row">${btn('上传真实图片','upload-item',x.id,'sm')}<small>PNG / JPG，最大 5 MB</small></div>`,btn('取消','close')+btn('保存修改','save-item','','primary'))}
function upload(id){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg';input.onchange=()=>{const f=input.files[0];if(!f)return;if(!['image/png','image/jpeg'].includes(f.type)||f.size>5*1024*1024){toast('请选择不超过 5 MB 的 PNG 或 JPG');return}const reader=new FileReader();reader.onload=()=>{const im=new Image();im.onload=()=>{const scale=Math.min(1,1000/Math.max(im.width,im.height)),cv=document.createElement('canvas');cv.width=Math.round(im.width*scale);cv.height=Math.round(im.height*scale);cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);checkpoint();if(id==='logo')s.logo=cv.toDataURL('image/png');else{s.items.find(x=>x.id===id).image=cv.toDataURL('image/jpeg',.88)}dirty(s.step<7);close();render();toast('图片已处理并保存在本机草稿中')};im.onerror=()=>toast('无法读取图片，请重新选择');im.src=reader.result};reader.readAsDataURL(f)};input.click()}
async function generation(){error='';if(!M.canGenerate(s)||!Ref.ready(s)){error='请先完成材料体检，并在视觉方向中确认参考样稿。';render();return}const token=++job;busy={type:'generate',progress:10};render();for(const n of [35,65,95]){await new Promise(r=>setTimeout(r,480));if(token!==job)return;busy.progress=n;render()}busy=null;if(failGenerate){failGenerate=false;error='演示：本次生成失败。材料和页序已保留，可点击「生成我的菜单」重试。';render();return}checkpoint();s.generated=true;s.maxStep=8;s.step=7;s.page=0;s.selected=null;s.overrides={};s.variant=0;dirty();render();toast('菜单生成完成，可以开始微调')}
async function doExport(){if(!exportAllowed())return;const token=++job;error='';clearFiles();const frozen=structuredClone(s);busy={type:'export',progress:8};render();try{await new Promise(r=>setTimeout(r,400));if(token!==job)return;if(failExport){failExport=false;throw Error('演示：文件生成失败，未发布任何不完整文件。请重试。')}const result=await MenuExport.build(frozen,p=>{if(token===job){busy.progress=p;render()}});if(token!==job)return;const published=await MenuExport.publish(result);if(token!==job)return;files=published;busy=null;render()}catch(e){if(token!==job)return;busy=null;error=e.message;render()}}
async function act(a,id){if(busy&&!['cancel-job','about','close'].includes(a))return;
if(a.startsWith('ref-')){await referenceAction(a.slice(4),id);return;}
if(a==='close'){close();return}if(a==='about'){modal('这个原型可以体验什么？',`<p>工具的唯一目标是：<strong>设计静态电子菜单，并导出为图片或 PDF。</strong></p><h3 style="margin-top:20px">实际可用</h3><p>八步向导、商品与价格修改、本地图片上传、上传参考图、原创参考图库、多种构图样稿、分页与页序、组件选择/拖动/属性调整/锁定/撤销、本机草稿、PNG/JPG/ZIP/栅格 PDF 下载。</p><h3 style="margin-top:20px">明确模拟</h3><p>AI 生成、来源菜单更新、失败场景是本地演示；预检只涵盖基础字段、边界与重叠。PDF 为图片封装，非正式矢量或印刷交付。</p><h3 style="margin-top:20px">不在范围内</h3><p>交互点餐、下单支付、POS 写回、设备发布、云端账户与生产级版本管理。</p>`);return}
if(a==='new'){if(saved){modal('创建新菜单',`<p>当前浏览器已有「${E(saved.name)}」草稿。新建将替换本机草稿，你也可以继续已有设计。</p>`,btn('继续已有草稿','resume')+btn('确认新建','new-confirm','','primary'));return}a='new-confirm'}
if(a==='new-confirm'){s=M.create();home=false;undo=[];clearFiles();close();save();render();return}if(a==='resume'){s=structuredClone(saved);home=false;close();render();return}if(a==='duplicate'){s=structuredClone(saved);s.name+=' · 副本';home=false;save();render();toast('已创建副本并替换本机活动草稿');return}if(a==='home'){home=true;save();render();return}
if(a==='next'){if(M.canContinue(s)){s.maxStep=Math.max(s.maxStep,s.step+1);moveStep(s.step+1)}return}if(a==='prev'){moveStep(s.step-1);return}if(a==='goto'){moveStep(Number(id));return}
if(a==='rotate-profile'&&['ipad-mini-6','ipad-8','ipad-9','ipad-10','screen-2000-1200','screen-1920-1200'].includes(s.profile)){checkpoint();[s.width,s.height]=[s.height,s.width];dirty(true)}
if(a==='profile'){checkpoint();const p={landscape:[1920,1080,'px'],portrait:[1080,1920,'px'],a4:[210,297,'mm'],a3:[297,420,'mm'],'ipad-mini-6':[2266,1488,'px'],'ipad-8':[2160,1620,'px'],'ipad-9':[2160,1620,'px'],'ipad-10':[2360,1640,'px'],'screen-2000-1200':[2000,1200,'px'],'screen-1920-1200':[1920,1200,'px'],custom:[1920,1080,'px']}[id];s.profile=id;[s.width,s.height,s.unit]=p;dirty(true)}
if(a==='category'){checkpoint();const group=s.items.filter(x=>x.category===id),all=group.every(x=>x.included);group.forEach(x=>x.included=!all);s.checked=false;dirty(true)}
if(a==='edit-item'){itemDialog(id);return}if(a==='add-item'){checkpoint();const id='d'+Date.now();s.items.push({id,name:'新增商品',en:'',price:null,category:'招牌料理',included:true,art:false,image:'',kind:0});dirty(true);render();itemDialog(id);return}
if(a==='save-item'){const name=document.querySelector('#item-name').value.trim(),en=document.querySelector('#item-en').value.trim(),raw=document.querySelector('#item-price').value;if(!name||raw===''||!Number.isFinite(Number(raw))||Number(raw)<0){document.querySelector('#item-error').textContent='请填写名称与有效的非负价格（零元允许）。';return}checkpoint();const x=s.items.find(x=>x.id===document.querySelector('#item-id').value);Object.assign(x,{name,en,price:Number(raw)});s.checked=false;dirty(true);close()}
if(a.startsWith('brand-')){brandAction(a,id);return;}
if(a==='upload-logo'){upload('logo');return}if(a==='upload-item'){if(s.overrides[id]?.locked){toast('请先解除锁定再替换图片');return}upload(id);return}if(a==='check'){s.checked=true;save()}if(a==='repair'){const x=M.items(s).find(x=>x.price===null||!x.name.trim());if(x){itemDialog(x.id);return}moveStep(3);return}if(a==='no-image'){s.noImage=true;save()}
if(a==='goal'){s.goal=id;dirty(true)}if(a==='style'){s.style=id;dirty(true)}
if(a==='page-up'||a==='page-down'){const p=M.pages(s).map(x=>x.id),i=Number(id),j=i+(a==='page-up'?-1:1);[p[i],p[j]]=[p[j],p[i]];s.pageOrder=p;s.generated=false;dirty()}
if(a==='generate'){await generation();return}if(a==='cancel-job'){job++;if(busy?.type==='analysis'){Ref.ensure(s).analysis.status='cancelled';save();}busy=null;error='已取消，当前草稿保留。';render();return}
if(a==='page'){s.page=Number(id);s.selected=null;save()}if(a==='pick-component'){s.selected=id;save()}
if(a==='lock'){if(!s.selected)return;checkpoint();const pos=R.positions(s,M.pages(s)[s.page]).find(x=>x.item.id===s.selected);s.overrides[s.selected]={...s.overrides[s.selected],x:pos.x,y:pos.y,scale:pos.scale,cw:pos.cw,ch:pos.ch,locked:!pos.locked};dirty()}
if(a==='undo'){if(undo.length){s=undo.pop();clearFiles();error='';save();toast('已撤销最近一次修改')}}
if(a==='editor-style'){if(Object.values(s.overrides).some(o=>o.locked)){toast('请先解除组件锁定，再修改整份菜单风格');return}checkpoint();s.style=id;if(s.aiDesign)s.aiDesign.palette=R.palettes[id];dirty()}
if(a==='regenerate'){const before=structuredClone(s),p=M.pages(s)[s.page],slots=R.positions(s,p).filter(x=>!x.locked),coords=slots.map(x=>({x:x.x,y:x.y,cw:x.cw,ch:x.ch,scale:x.scale})).reverse();slots.forEach((x,i)=>{s.overrides[x.item.id]={...s.overrides[x.item.id],...coords[i]}});if(layoutErrors().length){s=before;error='局部重生成存在位置冲突，未改变原稿。请调整或解除冲突组件的锁定后重试。'}else{undo.push(before);dirty();error='';toast(`已重排当前页 ${slots.length} 个未锁定组件，锁定组件保持不变`)}}
if(a==='preview'){modal('成品预览（无编辑标记）',R.svg(s,M.pages(s)[s.page]));return}
if(a==='scenarios'){modal('演示场景',`<p class="hint">仅用于评审异常流程，不影响真实餐厅数据。</p><div class="test-controls">${btn('下一次生成失败一次','fail-generate')}${btn('下一次导出失败一次','fail-export')}${btn('模拟来源菜单价格更新','mark-stale')}${btn('重新体验材料缺价','missing-price')}</div>`);return}
if(a==='fail-generate'){failGenerate=true;close();moveStep(6);toast('已启用一次生成失败演示');return}if(a==='fail-export'){failExport=true;close();toast('已启用一次导出失败演示');return}if(a==='mark-stale'){s.stale=true;s.staleAccepted=false;clearFiles();save();close();toast('已模拟来源菜单版本更新')}
if(a==='missing-price'){checkpoint();s.items[5].price=null;s.checked=false;s.generated=false;s.maxStep=4;s.step=4;dirty();close()}
if(a==='stale-dialog'){modal('来源菜单有新版本',`<p>演示差异：${E(s.items[0].name)} 的价格从 ¥${s.items[0].price} 更新为 ¥${Number(s.items[0].price)+2}。</p>${notice('刷新将创建更新后的草稿，原型只保存当前活动草稿，不提供历史版本库。','warn')}`,btn('按已保存内容导出','keep-snapshot')+btn('刷新并重新检查','refresh-snapshot','','primary'));return}
if(a==='keep-snapshot'){s.staleAccepted=true;save();close()}if(a==='refresh-snapshot'){checkpoint();s.items[0].price=Number(s.items[0].price)+2;s.stale=false;s.staleAccepted=false;dirty();close();toast('已更新草稿价格，请重新核对并确认导出')}
if(a==='export'){await doExport();return}if(a==='export-again'){clearFiles();s.exportWarning=false;save()}if(a==='download'){const f=files[Number(id)],link=document.createElement('a');link.href=f.url;link.download=f.name;link.click();toast('已发起下载：'+f.name);return}
render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)act(b.dataset.action,b.dataset.id).catch(err=>{console.error('Menu Studio action failed:',b.dataset.action,err);error=err.message;busy=null;render();toast('操作失败：'+err.message)})});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.itemCheck){checkpoint();s.items.find(x=>x.id===el.dataset.itemCheck).included=el.checked;s.checked=false;dirty(true);render();return}const k=el.dataset.field;if(!k)return;if(k.startsWith('brandmat-')){changeBrand(k.slice(9),el.value);return;}if(k.startsWith('ref-')){referenceChange(k.slice(4),el.type==='checkbox'?el.checked:el.value);return;}const v=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(intentFields.includes(k)){updateIntent(k,v);return;}if(k.startsWith('component-')){const x=s.items.find(x=>x.id===s.selected);if(!x)return;const o=s.overrides[x.id]||{};if(o.locked){toast('请先解除锁定再编辑');render();return}checkpoint();const key=k.slice(10);if(key==='name')x.name=String(v);else if(key==='price')x.price=el.value===''?null:Number(v);else{s.overrides[x.id]={...o,[key]:key==='scale'?Math.max(.7,Math.min(1.1,v)):v}}dirty()}else{const regenerate=['name','brand','subtitle','width','height','dpi','featured','language','density','promo'].includes(k);s[k]=k==='density'?Number(v):v;if(['warnings','noImage','exportWarning','pdfWarning','range','filename','format'].includes(k)){clearFiles();save()}else dirty(regenerate)}render()});
let drag=null;
document.addEventListener('pointerdown',e=>{const g=e.target.closest('#editor-canvas g[data-component]');if(!g||e.button!==0)return;const id=g.dataset.component,svg=g.ownerSVGElement,pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const start=pt.matrixTransform(svg.getScreenCTM().inverse()),pos=R.positions(s,M.pages(s)[s.page]).find(x=>x.item.id===id);drag={id,g,svg,start,pos,moved:false,before:structuredClone(s)};g.setPointerCapture(e.pointerId)});
document.addEventListener('pointermove',e=>{if(!drag||drag.pos.locked)return;const pt=drag.svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const p=pt.matrixTransform(drag.svg.getScreenCTM().inverse()),dx=p.x-drag.start.x,dy=p.y-drag.start.y;if(Math.abs(dx)+Math.abs(dy)>3)drag.moved=true;if(drag.moved){const x=drag.pos.x+dx,y=drag.pos.y+dy;s.overrides[drag.id]={...s.overrides[drag.id],x,y};drag.g.setAttribute('transform',`translate(${x} ${y}) scale(${drag.pos.scale})`)}});
document.addEventListener('pointerup',()=>{if(!drag)return;const d=drag;drag=null;s.selected=d.id;if(d.moved){undo.push(d.before);dirty()}else save();render()});
window.addEventListener('beforeunload',()=>{if(!home)save()});
render();
document.addEventListener('toggle',e=>{if(e.target?.classList?.contains('intent-advanced'))intentAdvancedOpen=e.target.open;},true);
